return $input.all().map(({ json }) => {
  const fileName = String(json.name || json.fileName || '').trim();
  const mimeType = String(json.mimeType || '').toLowerCase();
  const supportedVideo = /\.(mp4|mov|m4v|webm|avi)$/i.test(fileName);
  const isVideo = mimeType.startsWith('video/') || supportedVideo;
  const topic = fileName.replace(/\.[^.]+$/, '').replace(/[_-]+/g, ' ').trim();

  return {
    json: {
      ...json,
      isVideo,
      topic,
      fileId: json.id || json.fileId,
      fileName,
    },
  };
});

const ai = $json || {};
const texts = [];

const walk = (value, depth = 0) => {
  if (depth > 8 || value == null) return;
  if (typeof value === 'string') {
    if (value.trim()) texts.push(value.trim());
    return;
  }
  if (Array.isArray(value)) {
    value.forEach((item) => walk(item, depth + 1));
    return;
  }
  if (typeof value === 'object') {
    Object.values(value).forEach((item) => walk(item, depth + 1));
  }
};

walk(ai);
const raw = texts.find((text) => text.includes('{')) || texts.sort((a, b) => b.length - a.length)[0] || '';
let parsed = {};
try {
  parsed = JSON.parse(raw);
} catch {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start >= 0 && end > start) {
    try { parsed = JSON.parse(raw.slice(start, end + 1)); } catch {}
  }
}

const file = $('Google Drive - Quét file trong folder').item.json;
const youtubeTitle = String(parsed.youtubeTitle || '').trim().slice(0, 100);
const youtubeDescription = String(parsed.youtubeDescription || '').trim();
const youtubeContent = String(parsed.youtube || youtubeDescription).trim();
if (!youtubeTitle || !youtubeDescription || !youtubeContent) {
  throw new Error(`AI chưa tạo đủ nội dung cho file: ${file.name || file.id}`);
}

return {
  json: {
    sourceRowId: `google-drive-${String(file.id)}`,
    employeeName: 'Google Drive',
    originalNote: `Video Drive: ${String(file.name || '').trim()}`,
    postType: 'youtube_short',
    videoFileId: String(file.id),
    videoFileName: String(file.name || 'video.mp4'),
    youtubeTitle,
    youtubeDescription,
    youtubeContent,
  },
};
